import RNA
import random
random.seed(1)
target='......(......((((.....))))......)......................'
n=len(target)
pairs=[(16,22),(15,23),(14,24),(13,25),(6,32)]
paired=set()
for i,j in pairs:
    paired.add(i);paired.add(j)
def rand_init():
    s=['A']*n
    for i,j in pairs:
        s[i]='G';s[j]='C'
    return s
def bpdist(ss,t):
    # compute from dot-bracket
    def pts(d):
        st=[];p=[]
        for i,c in enumerate(d):
            if c=='(':st.append(i)
            elif c==')':p.append((st.pop(),i))
        return set(p)
    return len(pts(ss).symmetric_difference(pts(t)))
best=None;bestd=99
for trial in range(30000):
    s=rand_init()
    for i in range(n):
        if i not in paired and random.random()<0.5:
            s[i]=random.choice('ACGU')
    seq=''.join(s)
    fc=RNA.fold_compound(seq)
    mfe,ss=fc.mfe()
    d=bpdist(ss,target)
    if d==0:
        print('SOLVED',seq)
        best=seq;break
    if d<bestd:
        bestd=d;best=seq
print('bestd',bestd, best)
EOF

